"use client";

import { FormEvent, useEffect, useRef, useState } from "react";
import { Activity, AlertTriangle, ArrowLeft, ArrowRight, Bell, Bot, Check, ChevronRight, CircleHelp, Clock3, DoorOpen, Home, LockKeyhole, Menu, MessageCircle, Mic, MoreHorizontal, Plus, RefreshCw, Search, Settings, ShieldCheck, Sparkles, Thermometer, UserRound, Users, Wifi, X, Zap } from "lucide-react";
import type { Authorization, Device, Event, EventStatus, FamilyMember, RiskLevel, Task } from "@/src/models";
import { eventStatusLabel, policyLabel, priorityLabel, riskLabel, taskStatusLabel } from "@/src/models";
import { productStore, useProductStore } from "@/src/stores/productStore";
import { isAuthorizationPolicyAllowed } from "@/lib/product-policy";
import { selectDashboardSummary } from "@/lib/product-selectors";
import { authApi } from "@/src/api/authApi";
import { ensurePushSubscription } from "@/src/api/pushApi";
import { apiRequest } from "@/src/api/apiClient";

const navItems = [
  ["/", "首页", Home], ["/ai", "AI 助手", Sparkles], ["/events", "事件中心", Activity], ["/tasks", "家庭任务", Check], ["/authorizations", "授权中心", ShieldCheck], ["/members", "家庭成员", Users], ["/devices", "智能设备", Wifi], ["/services", "服务资源", CircleHelp], ["/audit", "安全与审计", LockKeyhole],
] as const;
const mobileItems = [["/", "首页", Home], ["/ai", "AI", Sparkles], ["/tasks", "任务", Check], ["/events", "事件", Activity], ["/members", "我的", UserRound]] as const;
type IconType = typeof Home;

function Icon({ icon: I, size = 17 }: { icon: IconType; size?: number }) { return <I size={size} strokeWidth={1.8} aria-hidden="true" />; }
function navigate(path: string) { window.history.pushState({}, "", path); window.dispatchEvent(new PopStateEvent("popstate")); }
function usePath(initialPath: string) { const [path, setPath] = useState(initialPath); useEffect(() => { const fn = () => setPath(window.location.pathname); fn(); window.addEventListener("popstate", fn); return () => window.removeEventListener("popstate", fn); }, []); return path; }

function RiskBadge({ level }: { level: RiskLevel }) { return <span className={`badge risk-${level}`}><i />{riskLabel[level]}</span>; }
function StatusBadge({ status }: { status: EventStatus | Task["status"] }) { const label = status in eventStatusLabel ? eventStatusLabel[status as EventStatus] : taskStatusLabel[status as Task["status"]]; return <span className="badge status"><i />{label}</span>; }
function Avatar({ member, size = "md" }: { member?: FamilyMember; size?: "sm" | "md" | "lg" | "xl" }) { return <span className={`avatar avatar-${size} tone-${member?.id.slice(-1) ?? "0"}`}>{member?.avatar ?? "家"}</span>; }
function Button({ children, onClick, variant = "primary", disabled = false, type = "button" }: { children: React.ReactNode; onClick?: () => void; variant?: "primary" | "secondary" | "quiet" | "danger"; disabled?: boolean; type?: "button" | "submit" }) { return <button type={type} className={`btn ${variant}`} onClick={onClick} disabled={disabled}>{children}</button>; }
function PageHeader({ eyebrow, title, description, action }: { eyebrow: string; title: string; description?: string; action?: React.ReactNode }) { return <div className="page-header"><div><div className="eyebrow">{eyebrow}</div><h1>{title}</h1>{description && <p>{description}</p>}</div>{action && <div className="header-actions">{action}</div>}</div>; }
function Panel({ children, className = "" }: { children: React.ReactNode; className?: string }) { return <section className={`panel ${className}`}>{children}</section>; }
function SectionTitle({ title, detail, action }: { title: string; detail?: string; action?: React.ReactNode }) { return <div className="section-title"><div><h2>{title}</h2>{detail && <p>{detail}</p>}</div>{action}</div>; }
function EmptyState({ title, detail, action }: { title: string; detail: string; action?: React.ReactNode }) { return <div className="empty-state"><div className="empty-icon"><Check size={22} /></div><h3>{title}</h3><p>{detail}</p>{action}</div>; }
function LoadingSkeleton() { return <div className="loading-skeleton" role="status" aria-live="polite" aria-label="加载中"><span /><span /><span /><span /><span /><span /></div>; }
function Toast({ text, onClose }: { text: string; onClose: () => void }) { return <div className="toast" role="status" aria-live="polite"><Check size={17} /><span>{text}</span><button aria-label="关闭提示" onClick={onClose}><X size={15} /></button></div>; }
function useDialogFocusTrap(onClose: () => void) { const ref = useRef<HTMLDivElement>(null); useEffect(() => { const dialog = ref.current; if (!dialog) return; const previousFocus = document.activeElement instanceof HTMLElement ? document.activeElement : null; const background = Array.from(document.querySelectorAll<HTMLElement>(".sidebar,.topbar,.mobile-nav,.page-content > :not(.dialog-backdrop)")); const previousAria = background.map((element) => element.getAttribute("aria-hidden")); background.forEach((element) => { (element as HTMLElement & { inert: boolean }).inert = true; element.setAttribute("aria-hidden", "true"); }); const focusable = () => Array.from(dialog.querySelectorAll<HTMLElement>('button:not([disabled]),select:not([disabled]),textarea:not([disabled]),input:not([disabled]),[href],[tabindex]:not([tabindex="-1"])')); (focusable()[0] ?? dialog).focus(); const onKeyDown = (event: KeyboardEvent) => { if (event.key === "Escape") { event.preventDefault(); onClose(); return; } if (event.key !== "Tab") return; const items = focusable(); if (!items.length) { event.preventDefault(); dialog.focus(); return; } const first = items[0]; const last = items[items.length - 1]; if (event.shiftKey && (document.activeElement === first || !dialog.contains(document.activeElement))) { event.preventDefault(); last.focus(); } else if (!event.shiftKey && document.activeElement === last) { event.preventDefault(); first.focus(); } }; document.addEventListener("keydown", onKeyDown); return () => { document.removeEventListener("keydown", onKeyDown); background.forEach((element, index) => { (element as HTMLElement & { inert: boolean }).inert = false; const aria = previousAria[index]; if (aria === null) element.removeAttribute("aria-hidden"); else element.setAttribute("aria-hidden", aria); }); previousFocus?.focus(); }; }, [onClose]); return ref; }

function AppShell({ children, path }: { children: React.ReactNode; path: string }) {
  const state = useProductStore();
  const [mobileOpen, setMobileOpen] = useState(false);
  const unread = state.notifications.filter((n) => !n.read).length;
  const active = (target: string) => target === "/" ? path === "/" : path.startsWith(target);
  return <div className="app-shell"><a className="skip-link" href="#main-content">跳到主要内容</a>
    <aside className="sidebar">
      <button className="brand" onClick={() => navigate("/")}><span className="brand-mark"><span /><span /><span /></span><span><strong>家有备</strong><small>家庭安全协同 AI Agent</small></span></button>
      <button className="family-switcher" onClick={() => navigate("/settings")}><Avatar /><span><strong>{state.family.name}</strong><small><i className="online-dot" /> {state.members.filter((m) => m.online).length} 位成员在线</small></span><ChevronRight size={14} /></button>
      <nav className="main-nav">{navItems.map(([href, label, I]) => <button key={href} className={active(href) ? "active" : ""} onClick={() => navigate(href)}><Icon icon={I} /><span>{label}</span>{href === "/events" && state.events.some((e) => e.status === "pending_confirmation") && <em>1</em>}</button>)}</nav>
      <div className="sidebar-bottom"><div className="nav-divider" /><button className="nav-link" onClick={() => navigate("/notifications")}><Bell size={17} /><span>通知中心</span>{unread > 0 && <em>{unread}</em>}</button><button className="nav-link" onClick={() => navigate("/settings")}><Settings size={17} /><span>设置</span></button><div className="space-card"><span className="mode-dot" /> <span>{state.demoMode ? "Demo 家庭空间" : "真实家庭空间"}</span><small>{state.demoMode ? "Mock 演示模式" : "已连接云端 · 数据落库"}</small></div></div>
    </aside>
    <main className="main-area" id="main-content"><header className="topbar"><button className="mobile-menu" aria-label="打开菜单" onClick={() => setMobileOpen(true)}><Menu size={20} /></button><div className="crumb">家有备 <span>/</span> {path === "/" ? "家庭总览" : path.split("/")[1] === "ai" ? "AI 助手" : path.split("/")[1] || "首页"}</div><div className="topbar-actions"><button className="top-icon" aria-label="通知" onClick={() => navigate("/notifications")}><Bell size={18} />{unread > 0 && <i />}</button><button className="profile-chip" onClick={() => navigate("/settings")}><span className="avatar avatar-sm tone-3">{state.user.avatar}</span><span>{state.user.name}<small>{state.user.role}</small></span></button></div></header><div className="page-content">{state.hydrationStatus === "ready" && state.lastError && path !== "/ai" && <Panel className="error-state global-error"><AlertTriangle size={19} /><div><strong>数据同步未完成</strong><p>{state.lastError}</p></div><Button variant="secondary" onClick={() => productStore.clearError()}>关闭提示</Button></Panel>}{children}</div></main>
    <nav className="mobile-nav">{mobileItems.map(([href, label, I]) => <button key={href} className={active(href) ? "active" : ""} onClick={() => navigate(href)}><Icon icon={I} size={19} /><span>{label}</span></button>)}</nav>
    {mobileOpen && <div className="mobile-drawer-backdrop" onClick={() => setMobileOpen(false)}><aside className="mobile-drawer" onClick={(e) => e.stopPropagation()}><div className="mobile-drawer-head"><strong>全部功能</strong><button aria-label="关闭菜单" onClick={() => setMobileOpen(false)}><X size={18} /></button></div>{[["/authorizations", "授权中心", ShieldCheck], ["/members", "家庭成员", Users], ["/devices", "智能设备", Wifi], ["/services", "服务资源", CircleHelp], ["/audit", "安全与审计", LockKeyhole], ["/notifications", "通知中心", Bell], ["/settings", "设置", Settings], ["/demo", "Demo 控制台", Zap]].map(([href, label, I]) => <button className="drawer-link" key={String(href)} onClick={() => { setMobileOpen(false); navigate(String(href)); }}><Icon icon={I as IconType} /><span>{String(label)}</span><ChevronRight size={15} /></button>)}</aside></div>}
  </div>;
}

function Metric({ label, value, note, icon, tone = "teal" }: { label: string; value: string; note: string; icon: IconType; tone?: string }) { return <div className="metric-card"><span className={`metric-icon ${tone}`}><Icon icon={icon} size={18} /></span><div><span>{label}</span><strong>{value}</strong><small>{note}</small></div></div>; }
function EventCard({ event, onClick, members }: { event: Event; onClick: () => void; members: FamilyMember[] }) { return <button className="event-card" onClick={onClick}><div className="card-top"><RiskBadge level={event.riskLevel} /><StatusBadge status={event.status} /><span className="card-time">{event.createdAt.slice(11, 16)}</span></div><h3>{event.title}</h3><p>{event.description}</p><div className="card-foot"><span className="member-stack">{event.relatedMembers.slice(0, 3).map((id) => <Avatar key={id} member={members.find((m) => m.id === id)} size="sm" />)}</span><span>{event.relatedTasks.length} 项关联任务 <ChevronRight size={14} /></span></div></button>; }
function TaskCard({ task, members, onClick }: { task: Task; members: FamilyMember[]; onClick: () => void }) { const member = members.find((m) => m.id === task.assignee); return <button className="task-card" onClick={onClick}><div className="card-top"><span className={`priority priority-${task.priority}`}>{priorityLabel[task.priority]}优先级</span><StatusBadge status={task.status} /></div><h3>{task.title}</h3><p>{task.description}</p><div className="task-foot"><span><Avatar member={member} size="sm" /> {member?.name ?? task.assignee}</span><span><Clock3 size={13} /> {task.status === "overdue" ? "已超时" : `截止 ${task.dueAt.slice(11, 16)}`}</span></div></button>; }

function Dashboard() {
  const state = useProductStore(); const summary = selectDashboardSummary(state); const pendingTasks = state.tasks.filter((t) => ["waiting_confirmation", "to_receive", "overdue"].includes(t.status)); const activeEvents = summary.activeEvents.map((summaryEvent) => state.events.find((event) => event.id === summaryEvent.id)).filter((event): event is Event => Boolean(event));
  return <><PageHeader eyebrow="家庭驾驶舱" title={`晚上好，${state.user.name}`} description={summary.description} action={<Button onClick={() => navigate("/ai")}><Sparkles size={16} /> 告诉家有备发生了什么</Button>} />
    <section className={`dashboard-hero dashboard-risk-${summary.riskLevel}`}><div><span className={`hero-status hero-status-${summary.riskLevel}`}><i /> {summary.statusLabel}</span><h2>{summary.headline}</h2><p>{summary.description}</p><small className="hero-principle">AI 负责理解与规划，规则负责边界，人工负责关键确认。</small><div className="hero-actions"><Button onClick={() => summary.topEvent ? navigate(`/events/${summary.topEvent.id}`) : navigate("/ai")}><MessageCircle size={16} /> {summary.topEvent ? "处理当前事件" : "描述一个家庭情况"}</Button><button className="link-button" onClick={() => navigate("/events")}>查看事件中心 <ArrowRight size={15} /></button></div></div><div className="hero-visual"><div className="sun" /><div className="home-line"><Home size={84} strokeWidth={1} /></div><div className="orbit orbit-a" /><div className="orbit orbit-b" /></div></section>
    <div className="metrics-grid"><Metric label="家庭成员" value={`${summary.memberCount} 人`} note={`${state.members.filter((member) => member.role === "老人").length} 位重点照护`} icon={Users} tone="teal" /><Metric label="待确认授权" value={`${summary.pendingAuthorizationCount} 项`} note={`${summary.criticalAuthorizationCount} 项高风险`} icon={ShieldCheck} tone="amber" /><Metric label="当前异常事件" value={`${activeEvents.length} 个`} note="按风险优先展示" icon={AlertTriangle} tone="rose" /><Metric label="设备状态" value={`${summary.onlineDeviceCount}/${state.devices.length}`} note={`${summary.offlineDeviceCount} 台离线待处理`} icon={Wifi} tone="blue" /></div>
    <div className="dashboard-grid"><Panel className="events-panel"><SectionTitle title="当前异常事件" detail="需要关注的家庭信号" action={<button className="link-button" onClick={() => navigate("/events")}>全部事件 <ArrowRight size={14} /></button>} /><div className="event-list">{activeEvents.slice(0, 3).map((e) => <EventCard key={e.id} event={e} members={state.members} onClick={() => navigate(`/events/${e.id}`)} />)}</div>{activeEvents.length === 0 && <EmptyState title="当前没有进行中的事件" detail="家庭状态良好，系统会持续保持低打扰监测。" />}</Panel><Panel className="tasks-panel"><SectionTitle title="今日待办" detail="先处理需要你确认的事项" action={<button className="link-button" onClick={() => navigate("/tasks")}>查看任务 <ArrowRight size={14} /></button>} /><div className="task-list">{pendingTasks.slice(0, 3).map((t) => <TaskCard key={t.id} task={t} members={state.members} onClick={() => navigate(`/tasks/${t.id}`)} />)}</div></Panel></div>
    <div className="dashboard-grid status-grid"><Panel><SectionTitle title="家庭成员状态" detail="仅显示粗粒度位置和协同状态" action={<button className="link-button" onClick={() => navigate("/members")}>全部成员 <ArrowRight size={14} /></button>} /><div className="family-status-list">{state.members.slice(0, 4).map((member) => <button className="member-status-row" key={member.id} onClick={() => navigate(`/members/${member.id}`)}><Avatar member={member} /><span><strong>{member.name}</strong><small>{member.role} · {member.location}</small></span><span className={member.online ? "online-state" : "offline-state"}><i />{member.currentTaskId ? "有任务" : member.online ? "在线" : "离线"}</span><ChevronRight size={14} /></button>)}</div></Panel><Panel><SectionTitle title="设备状态" detail="异常、离线和高风险设备优先" action={<button className="link-button" onClick={() => navigate("/devices")}>全部设备 <ArrowRight size={14} /></button>} /><div className="family-status-list">{[...state.devices].sort((a, b) => Number(a.online) - Number(b.online) || Number(b.riskLevel !== "normal") - Number(a.riskLevel !== "normal")).slice(0, 4).map((device) => <button className="member-status-row" key={device.id} onClick={() => navigate(`/devices/${device.id}`)}><span className={`mini-icon ${device.online ? "" : "rose"}`}><Wifi size={15} /></span><span><strong>{device.name}</strong><small>{device.room} · {device.reading}</small></span><RiskBadge level={device.riskLevel} /><ChevronRight size={14} /></button>)}</div></Panel></div>
    <div className="dashboard-grid lower"><Panel><SectionTitle title="AI 今日建议" detail="基于家庭档案和近期活动" /><div className="advice"><span className="advice-icon"><Sparkles size={18} /></span><div><strong>补齐“陌生访客”家庭预案</strong><p>门锁属于高风险设备。建议提前约定家庭成员的确认顺序和拒绝后处理方式。</p></div><button aria-label="查看陌生访客授权建议" onClick={() => navigate("/authorizations")}><ChevronRight size={17} /></button></div><div className="advice"><span className="advice-icon soft"><Clock3 size={18} /></span><div><strong>确认林阿姨的夜间联系人</strong><p>当前临时照护者王阿姨的授权将在今晚 22:00 到期。</p></div><button aria-label="查看王阿姨的夜间联系人设置" onClick={() => navigate("/members/M005")}><ChevronRight size={17} /></button></div></Panel><Panel><SectionTitle title="最近活动" detail="每一步都有来源和记录" action={<button className="link-button" onClick={() => navigate("/audit")}>审计记录 <ArrowRight size={14} /></button>} /><div className="activity-list">{state.auditLogs.slice(0, 4).map((log) => <div className="activity-row" key={log.id}><span className={`activity-dot ${log.result}`} /><div><strong>{log.action}</strong><p>{log.actor} · {log.target}</p></div><time>{log.time}</time></div>)}</div></Panel></div>
  </>;
}

function EventsPage() { const state = useProductStore(); const [filter, setFilter] = useState("all"); const [query, setQuery] = useState(""); const list = state.events.filter((e) => (filter === "all" || e.status === filter || e.riskLevel === filter) && `${e.title}${e.description}${e.relatedMembers.map((id) => state.members.find((m) => m.id === id)?.name ?? "").join("")}`.toLowerCase().includes(query.trim().toLowerCase())); return <><PageHeader eyebrow="持续跟进" title="事件中心" description="事件不是通知，而是一条从识别到解决的协同链路。" action={<Button onClick={() => navigate("/ai")}><Plus size={16} /> 创建事件</Button>} /><Panel className="toolbar"><div className="search-box"><Search size={16} /><input name="event-search" aria-label="搜索事件标题或成员" autoComplete="off" value={query} onChange={(e) => setQuery(e.target.value)} placeholder="搜索事件标题或成员…" /></div><div className="filter-tabs">{[["all", "全部"], ["pending_confirmation", "待确认"], ["processing", "处理中"], ["resolved", "已解决"]].map(([key, label]) => <button key={key} className={filter === key ? "active" : ""} onClick={() => setFilter(key)}>{label}<small>{key === "all" ? state.events.length : state.events.filter((e) => e.status === key).length}</small></button>)}</div></Panel><div className="event-grid">{list.map((e) => <EventCard key={e.id} event={e} members={state.members} onClick={() => navigate(`/events/${e.id}`)} />)}{list.length === 0 && <Panel className="event-empty"><EmptyState title="没有匹配的事件" detail="尝试其他关键词或切换事件状态。" /></Panel>}</div></>; }

function Timeline({ event }: { event: Event }) { return <div className="timeline">{event.timeline.map((item, index) => <div className="timeline-item" key={item.id}><div className={`timeline-marker ${item.tone}`}>{item.tone === "success" ? <Check size={13} /> : <span>{index + 1}</span>}</div><div><time>{item.time}</time><h4>{item.title}</h4><p>{item.detail}</p><small>{item.actor}</small></div></div>)}</div>; }
function EventDetail({ id }: { id: string }) { const state = useProductStore(); const event = state.events.find((e) => e.id === id); const [ownerMenu, setOwnerMenu] = useState(false); if (!event) return <NotFound title="内容不存在" detail={`未找到事件 ${id}，没有执行任何关联操作。`} backPath="/events" />; const task = state.tasks.find((t) => t.id === event.relatedTasks[0]); const auth = state.authorizations.find((a) => a.id === event.relatedAuthorizationId); const eventDevices = event.relatedDevices.map((deviceId) => state.devices.find((d) => d.id === deviceId)).filter((d): d is Device => Boolean(d)); const eventLogs = state.auditLogs.filter((log) => log.target.includes(event.id) || event.relatedDevices.some((deviceId) => log.target.includes(deviceId))).slice(0, 5); return <><button className="back-button" onClick={() => navigate("/events")}><ArrowLeft size={15} /> 返回事件中心</button><PageHeader eyebrow={`事件 ${event.id}`} title={event.title} description={event.description} action={<><RiskBadge level={event.riskLevel} /><StatusBadge status={event.status} /></>} /><div className="detail-layout"><div><Panel className="event-detail-banner"><div className="detail-icon"><Activity size={22} /></div><div><span>AI 判断</span><h2>{event.aiAssessment}</h2><p>来源：{event.source} · 更新时间 {event.updatedAt.slice(11, 16)}</p></div></Panel><Panel><SectionTitle title="事件时间线" detail="理解、规划、协同、确认与回传" action={<span className="live-label"><i />实时同步</span>} /><Timeline event={event} /></Panel><Panel><SectionTitle title="设备状态" detail="本次判断使用的已授权设备信号" /><div className="event-device-grid">{eventDevices.map((d) => <button key={d.id} onClick={() => navigate(`/devices/${d.id}`)}><span className={`device-icon ${d.kind}`}><Wifi size={16} /></span><span><strong>{d.name}</strong><small>{d.room} · {d.reading}</small></span><RiskBadge level={d.riskLevel} /><ChevronRight size={15} /></button>)}</div></Panel><Panel><SectionTitle title="操作日志" detail="事件、设备和人工确认统一留痕" />{eventLogs.length ? <div className="activity-list">{eventLogs.map((log) => <div className="activity-row" key={log.id}><span className={`activity-dot ${log.result}`} /><div><strong>{log.action}</strong><p>{log.actor} · {log.reason}</p></div><time>{log.time}</time></div>)}</div> : <EmptyState title="暂无额外操作日志" detail="事件时间线已记录当前全部动作。" />}</Panel></div><aside className="detail-aside"><Panel><SectionTitle title="当前责任人" /><div className="owner-row"><Avatar member={state.members.find((m) => m.id === "M003")} size="lg" /><div><strong>林晓</strong><p>家庭管理员 · 异地协同</p></div><button className="icon-plain" aria-label="更多负责人操作" onClick={() => setOwnerMenu(true)}><MoreHorizontal size={17} /></button></div><div className="mini-info"><span>涉及成员</span><strong>{event.relatedMembers.map((id) => state.members.find((m) => m.id === id)?.name).join("、")}</strong></div><div className="mini-info"><span>关联设备</span><strong>{event.relatedDevices.length} 台设备信号</strong></div></Panel><Panel><SectionTitle title="关联任务" /><button className="linked-row" onClick={() => task && navigate(`/tasks/${task.id}`)}><span className="mini-icon"><Check size={15} /></span><span><strong>{task?.title ?? "暂无任务"}</strong><small>{task ? taskStatusLabel[task.status] : ""}</small></span><ChevronRight size={16} /></button>{auth && <button className="linked-row" onClick={() => navigate(`/authorizations?focus=${auth.id}`)}><span className="mini-icon amber"><ShieldCheck size={15} /></span><span><strong>授权确认</strong><small>{auth.status === "pending" ? "等待人工确认" : policyLabel[auth.policy]}</small></span><ChevronRight size={16} /></button>}</Panel><Panel className="event-next-step"><SectionTitle title="下一步行动" detail="每次推进都会回写事件、任务和审计" />{event.status === "resolved" || event.status === "closed" ? <div className="success-block"><Check size={18} /> 事件已解决</div> : auth?.status === "pending" ? <Button onClick={() => navigate("/authorizations")}>前往人工授权 <ArrowRight size={15} /></Button> : <Button onClick={() => productStore.advanceEvent(event.id)}>推进下一步 <ArrowRight size={15} /></Button>}</Panel><Panel className="boundary-note"><ShieldCheck size={18} /><div><strong>安全边界</strong><p>AI 只负责理解与规划，门锁、摄像头、专业救援等高风险动作永远需要人工确认。</p></div></Panel></aside></div>{ownerMenu && <div className="dialog-backdrop" onClick={() => setOwnerMenu(false)}><div className="simple-dialog" onClick={(e) => e.stopPropagation()}><div className="dialog-warning"><Users size={21} /></div><h2>当前责任人 · 林晓</h2><p><strong>角色：</strong>家庭管理员 · 异地协同<br /><strong>电话：</strong>{state.members.find((m) => m.id === "M003")?.phone ?? "138****2140"}<br /><strong>当前位置：</strong>上海</p><div className="dialog-actions"><Button type="button" variant="quiet" onClick={() => setOwnerMenu(false)}>关闭</Button><Button type="button" onClick={() => { navigator.clipboard?.writeText(state.members.find((m) => m.id === "M003")?.phone ?? "138****2140").then(() => { notifyGlobal("联系电话已复制"); setOwnerMenu(false); }).catch(() => notifyGlobal("复制失败，请手动复制")); }}>复制电话</Button></div></div></div>}</>; }

function TasksPage() { const state = useProductStore(); const [tab, setTab] = useState("all"); const list = state.tasks.filter((t) => tab === "all" || (tab === "mine" ? t.assignee === "M003" : tab === "ai" ? t.creator.includes("AI") : t.status === "completed")); return <><PageHeader eyebrow="协同执行" title="家庭任务" description="每个异常都有责任人、截止时间和完成证据。" action={<Button onClick={() => navigate("/ai")}><Plus size={16} /> 新建任务</Button>} /><div className="segmented">{[["all", "全部任务"], ["mine", "我的任务"], ["ai", "AI 创建"], ["completed", "已完成"]].map(([k, l]) => <button key={k} className={tab === k ? "active" : ""} onClick={() => setTab(k)}>{l}</button>)}</div><Panel className="table-panel"><div className="task-table-head"><span>任务</span><span>负责人</span><span>来源事件</span><span>优先级</span><span>状态</span><span /></div>{list.map((t) => <TaskRow key={t.id} task={t} members={state.members} />)}</Panel></>; }
function TaskRow({ task, members }: { task: Task; members: FamilyMember[] }) { const member = members.find((m) => m.id === task.assignee); return <button className="task-row" onClick={() => navigate(`/tasks/${task.id}`)}><span className="task-name"><span className={`mini-icon ${task.status === "overdue" ? "rose" : ""}`}><Check size={14} /></span><span><strong>{task.title}</strong><small>截止 {task.dueAt.slice(11, 16)}</small></span></span><span className="assignee"><Avatar member={member} size="sm" />{member?.name}</span><span className="muted">{task.sourceEventId}</span><span className={`priority priority-${task.priority}`}>{priorityLabel[task.priority]}</span><StatusBadge status={task.status} /><ChevronRight size={16} /></button>; }
function TaskDetail({ id }: { id: string }) { const state = useProductStore(); const task = state.tasks.find((t) => t.id === id); const [action, setAction] = useState(""); const [taskError, setTaskError] = useState(""); const [transferTo, setTransferTo] = useState(false); if (!task) return <NotFound title="内容不存在" detail={`未找到任务 ${id}，没有修改其他家庭任务。`} backPath="/tasks" />; const event = state.events.find((e) => e.id === task.sourceEventId); const member = state.members.find((m) => m.id === task.assignee); const doAction = (key: "accept" | "complete" | "help") => { setAction(key); setTimeout(() => { const success = productStore.updateTask(task.id, key); if (!success && key === "complete") setTaskError("请先上传完成证据，再由家庭成员确认完成。"); else setTaskError(""); setAction(""); }, 260); }; const uploadEvidence = () => { productStore.uploadTaskEvidence(task.id); setTaskError(""); notifyGlobal("完成证据已上传，等待家庭确认"); }; return <><button className="back-button" onClick={() => navigate("/tasks")}><ArrowLeft size={15} /> 返回家庭任务</button><PageHeader eyebrow={`任务 ${task.id}`} title={task.title} description={task.description} action={<StatusBadge status={task.status} />} /><div className="detail-layout"><div><Panel className="why-panel"><span className="eyebrow">为什么创建</span><h2>来自事件：{event?.title}</h2><p>{event?.aiAssessment}</p><div className="source-chain"><span>事件识别</span><ArrowRight size={14} /><span>AI 拆解任务</span><ArrowRight size={14} /><span>家庭协同</span></div></Panel><Panel><SectionTitle title="执行进度" detail="状态回传会同步到事件时间线和审计日志" /><div className="task-progress"><div className="progress-line"><i style={{ width: task.status === "completed" ? "100%" : task.status === "in_progress" ? "55%" : "22%" }} /></div><div className="progress-label"><span>已创建</span><span>执行中</span><span>完成确认</span></div></div><div className="evidence-box"><div className="evidence-icon"><Check size={17} /></div><div><strong>完成证据</strong><p>{task.evidence ?? "先上传照片或填写结果；上传不会直接完成任务。"}</p></div><button className="link-button" onClick={uploadEvidence}>{task.evidence ? "更换照片占位" : "上传照片占位"}</button></div><div className={`family-confirmation ${task.familyConfirmedAt ? "confirmed" : ""}`}><ShieldCheck size={17} /><div><strong>家庭确认</strong><p>{task.familyConfirmedAt ? `已核对证据并确认完成 · ${task.familyConfirmedAt.slice(0, 16).replace("T", " ")}` : task.evidence ? "证据已就绪，等待家庭成员点击“确认完成”。" : "上传完成证据后才能进入家庭确认。"}</p></div></div></Panel></div><aside className="detail-aside"><Panel><SectionTitle title="任务负责人" /><div className="owner-row"><Avatar member={member} size="lg" /><div><strong>{member?.name}</strong><p>{member?.role} · {member?.location}</p></div></div><div className="mini-info"><span>截止时间</span><strong>{task.dueAt.slice(0, 10)} {task.dueAt.slice(11, 16)}</strong></div><div className="mini-info"><span>优先级</span><strong>{priorityLabel[task.priority]}优先级</strong></div></Panel><Panel className="action-panel"><SectionTitle title="需要你做什么" />{task.status !== "completed" && <><Button onClick={() => doAction("accept")} disabled={Boolean(action)}>{action === "accept" ? "保存中…" : "接受任务"}</Button><Button variant="secondary" onClick={() => doAction("complete")} disabled={Boolean(action)}>{action === "complete" ? "确认中…" : "确认完成"}</Button>{taskError && <div className="inline-error" role="alert"><AlertTriangle size={14} />{taskError}</div>}<Button variant="secondary" onClick={() => setTransferTo(true)}>转交任务</Button><Button variant="quiet" onClick={() => doAction("help")} disabled={Boolean(action)}>请求家庭成员帮助</Button></>}{task.status === "completed" && <div className="success-block"><Check size={18} /> 任务已完成并留痕</div>}</Panel></aside></div>{transferTo && <div className="dialog-backdrop" onClick={() => setTransferTo(false)}><div className="simple-dialog" onClick={(e) => e.stopPropagation()}><div className="dialog-warning"><Users size={21} /></div><h2>转交任务给谁？</h2><div className="member-pick-list">{state.members.filter((m) => m.id !== task.assignee).map((m) => <button key={m.id} onClick={() => { productStore.transferTask(task.id, m.id); setTransferTo(false); productStore.audit(state.user.name, "user", task.id, "转交家庭任务", `转交给 ${m.name}`, "success", "attention"); notifyGlobal(`任务已转交给${m.name}`); }}><Avatar member={m} size="sm" /><span><strong>{m.name}</strong><small>{m.role} · {m.location}</small></span><ChevronRight size={15} /></button>)}</div></div></div>}</>; }

function AuthorizationsPage() { const state = useProductStore(); const [selectedId, setSelectedId] = useState<string | null>(state.authorizations.find((a) => a.status === "pending")?.id ?? null); const [tab, setTab] = useState<"pending" | "rules" | "history">("pending"); const pending = state.authorizations.filter((a) => a.status === "pending"); const history = state.authorizations.filter((a) => a.status === "approved" || a.status === "rejected"); const selected = state.authorizations.find((authorization) => authorization.id === selectedId); return <><PageHeader eyebrow="安全边界" title="授权中心" description="AI 想做什么、为什么要做、会产生什么后果，都由你决定。" action={<div className="policy-summary"><ShieldCheck size={18} /><span><strong>{pending.length}</strong> 项待确认</span></div>} /><Panel className="principle-banner"><div className="principle-icon"><ShieldCheck size={23} /></div><div><strong>AI 负责理解与规划，规则负责边界，人工负责关键确认。</strong><p>门锁、摄像头、敏感隐私共享和专业救援等动作不能通过默认授权静默执行。</p></div></Panel><div className="segmented auth-tabs"><button className={tab === "pending" ? "active" : ""} onClick={() => setTab("pending")}>待确认 <small>{pending.length}</small></button><button className={tab === "rules" ? "active" : ""} onClick={() => setTab("rules")}>我的规则</button><button className={tab === "history" ? "active" : ""} onClick={() => setTab("history")}>历史授权 <small>{history.length}</small></button></div><div className="auth-layout"><div>{tab === "pending" && <><SectionTitle title="待确认" detail="高风险操作会在这里等待你的决定" />{pending.map((a) => <AuthorizationCard key={a.id} auth={a} onClick={() => setSelectedId(a.id)} />)}{pending.length === 0 && <Panel><EmptyState title="暂无待确认授权" detail="当前没有需要你立即决定的高风险动作。" /></Panel>}</>}{tab === "rules" && <><SectionTitle title="我的规则" detail="长期规则可以随时修改" /><div className="rules-list">{state.authorizations.filter((a) => a.status === "active").map((a) => <RuleRow key={a.id} auth={a} />)}</div></>}{tab === "history" && <><SectionTitle title="历史授权" detail="每次人工决定都可追溯" /><div className="rules-list">{history.map((a) => <AuthorizationHistoryRow key={a.id} auth={a} />)}</div></>}</div><aside className="auth-side"><Panel><SectionTitle title="四级风险" /><div className="risk-legend">{(["normal", "attention", "warning", "critical"] as RiskLevel[]).map((r) => <div key={r}><RiskBadge level={r} /><p>{r === "normal" ? "读取低敏状态" : r === "attention" ? "创建任务与发送提醒" : r === "warning" ? "影响家庭安全的动作" : "门锁、摄像头、专业救援"}</p></div>)}</div></Panel><Panel className="policy-card"><LockKeyhole size={19} /><h3>门锁永远需要人工确认</h3><p>即使 AI 建议开门，也会先经过风险规则，再进入确认弹窗，不会直接调用设备。</p><button className="link-button" onClick={() => navigate("/events/E002")}>查看陌生访客事件 <ArrowRight size={14} /></button></Panel></aside></div>{selected && <RiskConfirmDialog auth={selected} onClose={() => setSelectedId(null)} onEditRules={() => { setSelectedId(null); setTab("rules"); }} />}</>; }
function AuthorizationCard({ auth, onClick }: { auth: Authorization; onClick: () => void }) { return <button className="authorization-card" onClick={onClick}><div className="auth-card-icon"><LockKeyhole size={20} /></div><div className="auth-card-content"><div className="card-top"><RiskBadge level={auth.riskLevel} /><span>{auth.createdAt.slice(11, 16)}</span></div><h3>{auth.action}</h3><p>{auth.reason}</p><div className="auth-resource"><span>资源</span>{auth.resource}<ChevronRight size={15} /></div></div></button>; }
function RuleRow({ auth }: { auth: Authorization }) { const allowedPolicies = Object.entries(policyLabel).filter(([key]) => isAuthorizationPolicyAllowed(auth, key as Authorization["policy"])); const change = (value: Authorization["policy"]) => { if (!productStore.setAuthorizationPolicy(auth.id, value)) notifyGlobal("该高风险资源不能设置为始终允许"); }; return <div className="rule-row"><div className="rule-icon"><ShieldCheck size={17} /></div><div><strong>{auth.action}</strong><p>{auth.resource} · {riskLabel[auth.riskLevel]}</p>{auth.riskLevel === "critical" && <small className="critical-rule-note">安全规则：仅支持每次询问或始终拒绝</small>}</div><select aria-label={`${auth.action}授权规则`} value={auth.policy} onChange={(e) => change(e.target.value as Authorization["policy"])}>{allowedPolicies.map(([k, v]) => <option key={k} value={k}>{v}</option>)}</select></div>; }
function AuthorizationHistoryRow({ auth }: { auth: Authorization }) { const approved = auth.status === "approved"; return <button className="history-auth-row" onClick={() => auth.eventId && navigate(`/events/${auth.eventId}`)}><span className={`history-result ${approved ? "approved" : "rejected"}`}>{approved ? <Check size={15} /> : <X size={15} />}</span><span><strong>{auth.action}</strong><p>{auth.resource} · {auth.reason}</p></span><span><RiskBadge level={auth.riskLevel} /><small>{approved ? "已允许" : "已拒绝"}</small></span><ChevronRight size={15} /></button>; }
function RiskConfirmDialog({ auth, onClose, onEditRules }: { auth: Authorization; onClose: () => void; onEditRules: () => void }) { const [busy, setBusy] = useState(false); const dialogRef = useDialogFocusTrap(onClose); const decide = async (d: "approve" | "reject") => { setBusy(true); const success = await productStore.confirmAuthorization(auth.id, d); setBusy(false); if (success) onClose(); else notifyGlobal("授权提交失败，设备未执行任何动作"); }; return <div className="dialog-backdrop" role="presentation" onClick={onClose}><div ref={dialogRef} className="risk-dialog" role="dialog" aria-modal="true" aria-label={`${auth.action}授权确认`} tabIndex={-1} onClick={(e) => e.stopPropagation()}><button className="dialog-close" aria-label="关闭" onClick={onClose}><X size={18} /></button><div className="dialog-warning"><AlertTriangle size={22} /></div><div className="eyebrow">需要你的确认 · {riskLabel[auth.riskLevel]}</div><h2>AI 想要“{auth.action}”</h2><div className="explain-grid"><div><span>为什么需要</span><p>{auth.reason}</p></div><div><span>涉及资源</span><p>{auth.resource}</p></div><div><span>可能后果</span><p>{auth.consequence}</p></div><div><span>长期规则</span><p>此次选择不会改变“每次询问”规则。</p></div></div><div className="dialog-note"><ShieldCheck size={16} /> 家有备不会在你确认前执行此操作。</div><div className="dialog-actions"><Button variant="quiet" onClick={() => decide("reject")} disabled={busy}>拒绝</Button><Button variant="primary" onClick={() => decide("approve")} disabled={busy}>{busy ? "记录中…" : "仅此次允许"}</Button></div><button className="rule-edit" onClick={onEditRules}>修改授权规则</button></div></div>; }

function Assistant() { const state = useProductStore(); const [input, setInput] = useState(""); const [thinking, setThinking] = useState(false); const [listening, setListening] = useState(false); const [showHistory, setShowHistory] = useState(false); const [attach, setAttach] = useState<string | null>(null); const fileRef = useRef<HTMLInputElement>(null); const startVoice = () => { if (listening) return; const w = window as unknown as { SpeechRecognition?: { new(): { lang: string; start(): void; onresult: ((e: { results: Array<Array<{ transcript: string }>> }) => void) | null; onerror: (() => void) | null; onend: (() => void) | null } }; webkitSpeechRecognition?: { new(): { lang: string; start(): void; onresult: ((e: { results: Array<Array<{ transcript: string }>> }) => void) | null; onerror: (() => void) | null; onend: (() => void) | null } } }; const SR = w.SpeechRecognition || w.webkitSpeechRecognition; if (SR) { const rec = new SR(); rec.lang = "zh-CN"; rec.onresult = (e) => { setInput(e.results[0][0].transcript); setListening(false); notifyGlobal("语音已识别"); }; rec.onerror = () => { setListening(false); notifyGlobal("语音识别失败，请重试"); }; rec.onend = () => setListening(false); setListening(true); rec.start(); } else { setListening(true); notifyGlobal("当前浏览器不支持语音识别，使用模拟输入…"); setTimeout(() => { setInput("我妈妈今天一直没有活动，帮我确认一下情况"); setListening(false); notifyGlobal("已填入模拟语音内容"); }, 900); } }; const send = async (e?: FormEvent) => { e?.preventDefault(); const value = (attach ? `[已附加现场图片：${attach}] ` : "") + input.trim(); if (!value) return; setThinking(true); await productStore.sendMessage(value); setInput(""); setAttach(null); setThinking(false); }; return <><PageHeader eyebrow="家庭安全协同" title="AI 助手" description="先理解情况，再给出行动；重要操作不会静默执行。" action={<Button variant="secondary" onClick={() => productStore.resetConversation()}><RefreshCw size={15} /> 新对话</Button>} />{state.lastError && <Panel className="error-state"><AlertTriangle size={19} /><div><strong>AI 服务暂时不可用</strong><p>{state.lastError}</p></div><Button variant="secondary" onClick={() => productStore.clearError()}>继续使用规则模式</Button></Panel>}<div className="assistant-layout"><Panel className="chat-panel"><div className="chat-head"><div className="agent-avatar"><Bot size={20} /></div><div><strong>家有备 Agent</strong><p><i className="online-dot" /> 已连接家庭记忆与安全规则</p></div><span className="model-tag">规则复核开启</span></div><div className="chat-stream">{state.aiMessages.map((m) => <div className={`message ${m.role}`} key={m.id}>{m.role === "assistant" && <div className="message-avatar"><Bot size={15} /></div>}<div className="bubble"><p>{m.text}</p>{m.cardType === "authorization" && <div className="ai-card risk-card"><div><LockKeyhole size={16} /><strong>高风险操作需要确认</strong></div><p>AI 无权直接打开入户门锁。请前往授权中心查看原因和后果。</p><button onClick={() => navigate("/authorizations")}>查看授权请求 <ArrowRight size={14} /></button></div>}{m.cardType === "task" && <div className="ai-card">{(() => { const rt = state.tasks.find((t) => t.id === m.relatedId); return <><div><Check size={16} /><strong>AI 已创建家庭任务</strong></div><p>{rt ? `${rt.title} · 责任人：${state.members.find((x) => x.id === rt.assignee)?.name ?? rt.assignee} · ${rt.status === "to_receive" ? "等待接受" : rt.status === "in_progress" ? "执行中" : "待确认"}` : "任务已创建，请前往任务中心查看"}</p><button onClick={() => navigate(rt ? `/tasks/${rt.id}` : "/tasks")}>查看任务 <ArrowRight size={14} /></button></>; })()}</div>}<small>{m.createdAt}</small></div>{m.role === "user" && <Avatar member={state.members.find((x) => x.id === "M003")} size="sm" />}</div>)}{thinking && <div className="message assistant"><div className="message-avatar"><Bot size={15} /></div><div className="bubble thinking"><i /><i /><i /> 正在读取家庭上下文…</div></div>}</div><form className="composer" onSubmit={send}><div className="quick-prompts"><button type="button" onClick={() => setInput("我爸今天晚上还没回家，帮我看看有没有异常")}>老人长时间未活动</button><button type="button" onClick={() => setInput("门口有个陌生人请求开门")}>陌生人请求开门</button><button type="button" onClick={() => setInput("厨房闻到燃气味，传感器也在报警")}>烟雾 / 燃气告警</button></div><div className="composer-box"><button type="button" className="attach-button" aria-label="上传图片" onClick={() => fileRef.current?.click()}><Plus size={18} /></button><input ref={fileRef} type="file" accept="image/*" style={{ display: "none" }} onChange={(e) => { const f = e.target.files?.[0]; if (f) { setAttach(f.name); notifyGlobal(`已附加现场图片：${f.name}`); } }} />{attach && <span className="attach-chip">{attach}<button type="button" aria-label="移除图片" onClick={() => setAttach(null)}>×</button></span>}<button type="button" className={`voice-button ${listening ? "listening" : ""}`} aria-label="语音输入" aria-pressed={listening} onClick={startVoice}><Mic size={17} /></button><textarea name="family-situation" aria-label="描述家庭情况" autoComplete="off" value={input} onChange={(e) => setInput(e.target.value)} placeholder="告诉家有备发生了什么…" rows={1} /><button className="send-button" type="submit" aria-label="发送消息" disabled={thinking || !input.trim()}><ArrowRight size={17} /></button></div><small>AI 输出仅用于协同建议，不构成医疗或消防专业判断。</small></form></Panel><aside className="assistant-aside"><Panel><SectionTitle title="本轮上下文" detail="仅使用已授权信息" /><div className="context-row"><Avatar member={state.members[0]} /><div><strong>林秀兰 · 68 岁</strong><p>独居 · 杭州文新街道</p></div><Check size={15} /></div><div className="context-row"><span className="context-icon"><DoorOpen size={16} /></span><div><strong>4 个已授权设备</strong><p>门磁、存在、烟雾、燃气</p></div><Check size={15} /></div><div className="context-row"><span className="context-icon amber"><ShieldCheck size={16} /></span><div><strong>关键动作需确认</strong><p>门锁与摄像头始终不自动执行</p></div><Check size={15} /></div></Panel><Panel><SectionTitle title="历史对话" action={<button className="link-button" onClick={() => setShowHistory(true)}>查看全部</button>} /><div className="history-row"><span>今天 · 老人安全确认</span><ChevronRight size={15} /></div><div className="history-row"><span>昨天 · 宠物照护提醒</span><ChevronRight size={15} /></div></Panel></aside></div>{showHistory && <div className="dialog-backdrop" onClick={() => setShowHistory(false)}><div className="simple-dialog" onClick={(e) => e.stopPropagation()}><div className="dialog-warning"><Bot size={21} /></div><h2>本次会话记录</h2><div className="history-dialog-list">{state.aiMessages.map((m) => <div key={m.id}><strong>{m.role === "user" ? "你" : "家有备 AI"}</strong><p>{m.text}</p></div>)}</div><div className="dialog-actions"><Button type="button" onClick={() => setShowHistory(false)}>关闭</Button></div></div></div>}</>; }

function AddItemDialog({ title, fields, busy, onSubmit, onClose }: { title: string; fields: { key: string; label: string; placeholder?: string; options?: string[] }[]; busy: boolean; onSubmit: (values: Record<string, string>) => void; onClose: () => void }) {
  const dialogRef = useDialogFocusTrap(onClose);
  const [values, setValues] = useState<Record<string, string>>({});
  const submit = (e: FormEvent) => { e.preventDefault(); onSubmit(values); };
  return <div className="dialog-backdrop" role="presentation" onClick={onClose}><div ref={dialogRef} className="add-dialog" role="dialog" aria-modal="true" aria-label={title} tabIndex={-1} onClick={(e) => e.stopPropagation()}><button type="button" className="dialog-close" aria-label="关闭" onClick={onClose}><X size={18} /></button><h2>{title}</h2><form onSubmit={submit}><div className="add-dialog-fields">{fields.map((f) => f.options ? <label key={f.key}><span>{f.label}</span><select value={values[f.key] ?? ""} onChange={(e) => setValues({ ...values, [f.key]: e.target.value })}>{f.options.map((o) => <option key={o} value={o}>{o}</option>)}</select></label> : <label key={f.key}><span>{f.label}</span><input value={values[f.key] ?? ""} placeholder={f.placeholder ?? ""} onChange={(e) => setValues({ ...values, [f.key]: e.target.value })} /></label>)}</div><div className="dialog-actions"><Button type="button" variant="quiet" onClick={onClose}>取消</Button><Button type="submit" disabled={busy}>{busy ? "保存中…" : "添加"}</Button></div></form></div></div>;
}

function MembersPage({ id }: { id?: string }) { const state = useProductStore(); const [adding, setAdding] = useState(false); const [busy, setBusy] = useState(false); if (id) return <MemberDetail id={id} />; const addMember = async (v: Record<string, string>) => { setBusy(true); try { await apiRequest("/api/members", { method: "POST", body: JSON.stringify({ name: v.name, relation: v.relation, role: v.role, phone: v.phone }) }); productStore.retryHydrate(); setAdding(false); notifyGlobal("家庭成员已添加"); } catch { notifyGlobal("添加失败，请重试"); } setBusy(false); }; return <><PageHeader eyebrow="家庭协同" title="家庭成员" description="按角色、位置和权限组织家庭协作，敏感信息只在授权范围内使用。" action={<Button onClick={() => setAdding(true)}><Plus size={16} /> 添加成员</Button>} /><div className="member-grid">{state.members.map((m) => <button className="member-card" key={m.id} onClick={() => navigate(`/members/${m.id}`)}><div className="member-card-top"><Avatar member={m} size="lg" /><span className={m.online ? "online-state" : "offline-state"}><i />{m.online ? "在线" : "离线"}</span></div><h3>{m.name}</h3><p>{m.relation} · {m.role}</p><div className="member-location"><Activity size={14} /> {m.location}</div><div className="member-card-foot"><span>{m.currentTaskId ? "有 1 项进行中任务" : "暂无待办任务"}</span><ChevronRight size={16} /></div></button>)}</div>{adding && <AddItemDialog title="添加家庭成员" fields={[{ key: "name", label: "姓名", placeholder: "如 张阿姨" }, { key: "relation", label: "与户主关系", placeholder: "如 母亲 / 邻居" }, { key: "role", label: "角色", placeholder: "如 家庭成员 / 临时照护者" }, { key: "phone", label: "联系电话", placeholder: "选填" }]} busy={busy} onSubmit={addMember} onClose={() => setAdding(false)} />}</>; }
function MemberDetail({ id }: { id: string }) { const state = useProductStore(); const m = state.members.find((x) => x.id === id); const [editing, setEditing] = useState(false); const [editBusy, setEditBusy] = useState(false); if (!m) return <NotFound title="内容不存在" detail={`未找到成员 ${id}，未显示其他成员的敏感信息。`} backPath="/members" />; const tasks = state.tasks.filter((t) => t.assignee === m.id); const accessibleDevices = m.role === "家庭管理员" ? state.devices : state.devices.filter((d) => m.role === "老人" ? ["D001", "D007", "D008"].includes(d.id) : m.role === "临时照护者" ? ["D001", "D003"].includes(d.id) : d.kind !== "camera" && d.kind !== "lock"); const recentLogs = state.auditLogs.filter((log) => log.actor === m.name || log.target.includes(m.name)).slice(0, 4); const saveMember = async (v: Record<string, string>) => { setEditBusy(true); try { await apiRequest(`/api/members/${m.id}`, { method: "PATCH", body: JSON.stringify({ name: v.name, relation: v.relation, role: v.role, phone: v.phone }) }); productStore.retryHydrate(); productStore.audit(state.user.name, "user", m.id, "编辑成员资料", `更新 ${m.name} 的资料`, "success", "normal"); setEditing(false); notifyGlobal("成员资料已更新"); } catch { notifyGlobal("保存失败，请重试"); } setEditBusy(false); }; return <><button className="back-button" onClick={() => navigate("/members")}><ArrowLeft size={15} /> 返回家庭成员</button><PageHeader eyebrow="成员详情" title={m.name} description={`${m.relation} · ${m.role}`} action={<span className={m.online ? "online-state" : "offline-state"}><i />{m.online ? "在线" : "离线"}</span>} /><div className="member-detail-grid"><Panel className="member-profile"><Avatar member={m} size="xl" /><h2>{m.name}</h2><p>{m.relation} · {m.role}</p><div className="profile-lines"><div><span>联系电话</span><strong>{m.phone}</strong></div><div><span>当前位置</span><strong>{m.location}</strong></div><div><span>紧急联系人</span><strong>{m.emergencyContact ? "已加入紧急联系人" : "未设置"}</strong></div></div><Button variant="secondary" onClick={() => setEditing(true)}>编辑成员资料</Button>{editing && <AddItemDialog title={`编辑 ${m.name} 的资料`} fields={[{ key: "name", label: "姓名" }, { key: "relation", label: "与户主关系" }, { key: "role", label: "角色" }, { key: "phone", label: "联系电话" }]} busy={editBusy} onSubmit={saveMember} onClose={() => setEditing(false)} />}</Panel><div className="member-detail-main"><Panel><SectionTitle title="当前任务" detail="与该成员相关的协同事项" />{tasks.map((t) => <TaskRow key={t.id} task={t} members={state.members} />)}</Panel><Panel><SectionTitle title="可访问设备" detail="只显示该角色授权范围内的设备" /><div className="compact-device-list">{accessibleDevices.slice(0, 5).map((d) => <button className="linked-row" key={d.id} onClick={() => navigate(`/devices/${d.id}`)}><span className="mini-icon"><Wifi size={15} /></span><span><strong>{d.name}</strong><small>{d.room} · {d.permission}</small></span><span className={d.online ? "online-state" : "offline-state"}><i />{d.online ? "在线" : "离线"}</span><ChevronRight size={15} /></button>)}</div></Panel><Panel><SectionTitle title="授权范围" detail="该成员可访问的内容" /><div className="permission-chips">{m.permissions.map((p) => <span key={p}><Check size={13} />{p}</span>)}</div></Panel><Panel><SectionTitle title="最近活动" detail="敏感操作和协同记录" />{recentLogs.length ? <div className="activity-list">{recentLogs.map((log) => <div className="activity-row" key={log.id}><span className={`activity-dot ${log.result}`} /><div><strong>{log.action}</strong><p>{log.target} · {log.reason}</p></div><time>{log.time}</time></div>)}</div> : <EmptyState title="暂无近期敏感操作" detail="该成员近期没有设备或授权操作。" />}</Panel></div></div></>; }

function DevicesPage({ id }: { id?: string }) { const state = useProductStore(); const [kind, setKind] = useState("全部"); const [adding, setAdding] = useState(false); const [busy, setBusy] = useState(false); if (id) return <DeviceDetail id={id} />; const kinds = ["全部", "安防", "环境", "照明", "门锁", "摄像头", "健康"]; const kindMap: Record<string, string> = { 安防: "security", 环境: "environment", 照明: "lighting", 门锁: "lock", 摄像头: "camera", 健康: "health" }; const list = state.devices.filter((d) => kind === "全部" || d.kind === kindMap[kind]); const addDevice = async (v: Record<string, string>) => { setBusy(true); try { await apiRequest("/api/devices", { method: "POST", body: JSON.stringify({ name: v.name, kind: v.kind, room: v.room }) }); productStore.retryHydrate(); setAdding(false); notifyGlobal("设备已添加（模拟设备，等待同步）"); } catch { notifyGlobal("添加失败，请重试"); } setBusy(false); }; return <><PageHeader eyebrow="家庭感知层" title="智能设备" description="统一读取家庭信号；设备是证据之一，不直接决定救援。" action={<><Button variant="secondary" onClick={() => { productStore.retryHydrate(); notifyGlobal("已从云端刷新设备状态"); }}><RefreshCw size={15} /> 刷新状态</Button><Button onClick={() => setAdding(true)}><Plus size={15} /> 添加设备</Button></>} /><Panel className="device-summary-bar"><div className="connection-status"><span className="connection-orb"><Wifi size={19} /></span><div><strong>本地模拟设备驱动</strong><p>Mock 演示模式 · 可切换 Home Assistant 适配器</p></div></div><div className="device-counts"><span><strong>{state.devices.filter((d) => d.online).length}</strong>在线</span><span><strong>{state.devices.filter((d) => !d.online).length}</strong>离线</span><span><strong>{state.devices.filter((d) => d.riskLevel !== "normal").length}</strong>需关注</span></div></Panel><div className="filter-tabs device-tabs">{kinds.map((k) => <button className={kind === k ? "active" : ""} key={k} onClick={() => setKind(k)}>{k}</button>)}</div><div className="device-grid">{list.map((d) => <DeviceCard key={d.id} device={d} />)}</div>{adding && <AddItemDialog title="添加设备" fields={[{ key: "name", label: "设备名称", placeholder: "如 阳台人体传感器" }, { key: "kind", label: "设备类型", options: ["environment", "security", "lighting", "health", "other"] }, { key: "room", label: "安装位置", placeholder: "如 阳台 / 卧室" }]} busy={busy} onSubmit={addDevice} onClose={() => setAdding(false)} />}</>; }
function DeviceCard({ device }: { device: Device }) { const icon = device.kind === "lock" ? LockKeyhole : device.kind === "environment" ? Thermometer : device.kind === "camera" ? Activity : device.kind === "lighting" ? Zap : Wifi; return <button className={`device-card ${device.riskLevel}`} onClick={() => navigate(`/devices/${device.id}`)}><div className="device-card-top"><span className={`device-icon ${device.kind}`}><Icon icon={icon} size={19} /></span><span className={device.online ? "online-state" : "offline-state"}><i />{device.online ? "在线" : "离线"}</span></div><span className="device-room">{device.room}</span><h3>{device.name}</h3><strong>{device.reading}</strong><p>{device.source === "real" ? "真实设备" : device.source === "local" ? "本地驱动" : "模拟设备"} · {device.permission}</p><div className="device-card-foot"><RiskBadge level={device.riskLevel} /><span>最后同步 {device.lastSync.slice(11, 16)}</span></div></button>; }
function DeviceDetail({ id }: { id: string }) { const state = useProductStore(); const d = state.devices.find((x) => x.id === id); const [showConfirm, setShowConfirm] = useState(false); if (!d) return <NotFound title="内容不存在" detail={`未找到设备 ${id}，没有执行任何设备动作。`} backPath="/devices" />; const events = state.events.filter((e) => d.relatedEventIds.includes(e.id)); const logs = state.auditLogs.filter((log) => log.target.includes(d.id) || log.target.includes(d.name)).slice(0, 5); const rules = d.kind === "lock" || d.kind === "camera" ? ["所有操作每次询问家庭管理员", "身份未验证时安全规则直接拦截", "每次拒绝与允许写入审计日志"] : d.kind === "environment" ? ["硬告警不能被 AI 降级", "离线超过 10 分钟通知家庭管理员", "恢复正常后仍需保留事件记录"] : ["离线状态自动通知", "每日同步一次状态摘要", "外部动作执行前检查授权等级"]; return <><button className="back-button" onClick={() => navigate("/devices")}><ArrowLeft size={15} /> 返回智能设备</button><PageHeader eyebrow="设备详情" title={d.name} description={`${d.room} · ${d.source === "real" ? "真实设备" : d.source === "local" ? "本地驱动" : "模拟设备"}`} action={<RiskBadge level={d.riskLevel} />} /><div className="device-detail-layout"><div><Panel className="device-status-large"><span className={`device-icon ${d.kind}`}><Wifi size={23} /></span><div><span>当前状态</span><h2>{d.reading}</h2><p>最后同步：{d.lastSync.slice(0, 16).replace("T", " ")}</p></div><span className={d.online ? "online-state" : "offline-state"}><i />{d.online ? "设备在线" : "设备离线"}</span></Panel><Panel><SectionTitle title="数据趋势" detail="Demo 模式展示最近 24 小时的状态变化" /><div className="fake-chart"><div className="chart-grid" /><svg viewBox="0 0 700 160" preserveAspectRatio="none"><path d="M0,120 C90,118 100,65 180,88 S260,130 340,84 S410,55 480,86 S590,110 700,42" /></svg><div className="chart-labels"><span>00:00</span><span>06:00</span><span>12:00</span><span>18:00</span><span>现在</span></div></div></Panel><Panel><SectionTitle title="自动化规则" detail="规则层负责确定性边界，不由模型自行修改" /><div className="automation-list">{rules.map((rule, index) => <div key={rule}><span>{index + 1}</span><p>{rule}</p><strong>{index === 0 && (d.kind === "lock" || d.kind === "camera") ? "强制" : "已启用"}</strong></div>)}</div></Panel></div><aside className="detail-aside"><Panel><SectionTitle title="安全控制" /><div className="device-boundary-card"><LockKeyhole size={17} /><div><strong>{d.kind === "lock" || d.kind === "camera" ? "高风险设备" : "低风险设备"}</strong><p>{d.permission}</p></div></div>{d.kind === "lock" || d.kind === "camera" ? <Button variant="secondary" onClick={() => setShowConfirm(true)}>查看授权边界</Button> : <Button onClick={() => notifyGlobal("低风险设备动作已进入人工确认")}>申请一次操作</Button>}</Panel><Panel><SectionTitle title="关联事件" />{events.length ? events.map((e) => <button className="linked-row" key={e.id} onClick={() => navigate(`/events/${e.id}`)}><span><strong>{e.title}</strong><small>{eventStatusLabel[e.status]}</small></span><ChevronRight size={15} /></button>) : <p className="muted">暂无关联事件</p>}</Panel><Panel><SectionTitle title="操作日志" detail="设备动作与安全拦截" />{logs.length ? <div className="activity-list">{logs.map((log) => <div className="activity-row" key={log.id}><span className={`activity-dot ${log.result}`} /><div><strong>{log.action}</strong><p>{log.actor} · {log.reason}</p></div><time>{log.time}</time></div>)}</div> : <EmptyState title="暂无设备操作" detail="状态读取不会触发外部动作。" />}</Panel></aside></div>{showConfirm && <div className="dialog-backdrop" onClick={() => setShowConfirm(false)}><div className="simple-dialog" onClick={(e) => e.stopPropagation()}><div className="dialog-warning"><LockKeyhole size={21} /></div><h2>高风险设备受保护</h2><p>门锁和摄像头不会出现一键执行。任何操作都需要先进入授权中心，由家庭成员确认。</p><Button onClick={() => { setShowConfirm(false); navigate("/authorizations") }}>前往授权中心</Button></div></div>}</>; }

function ServicesPage() { const state = useProductStore(); const [adding, setAdding] = useState(false); const [busy, setBusy] = useState(false); const [contactSvc, setContactSvc] = useState<null | { id: string; name: string; coverage: string; contact: string; verified: boolean }>(null); const [verifyBusy, setVerifyBusy] = useState(false); const addService = async (v: Record<string, string>) => { setBusy(true); try { await apiRequest("/api/services", { method: "POST", body: JSON.stringify({ name: v.name, category: v.category, coverage: v.coverage, contact: v.contact }) }); productStore.retryHydrate(); setAdding(false); notifyGlobal("服务资源已添加（未验证，不可用于紧急救援）"); } catch { notifyGlobal("添加失败，请重试"); } setBusy(false); }; const verifyService = async (s: { id: string; name: string }) => { setVerifyBusy(true); try { await apiRequest(`/api/services/${s.id}`, { method: "PATCH", body: JSON.stringify({ verified: true }) }); productStore.retryHydrate(); productStore.audit(state.user.name, "user", s.id, "验证服务资源", `管理员验证 ${s.name}，可参与紧急救援匹配`, "success", "normal"); notifyGlobal(`${s.name} 已验证，可用于紧急救援匹配`); } catch { notifyGlobal("验证失败，请重试"); } setVerifyBusy(false); }; return <><PageHeader eyebrow="家庭外部协同" title="服务资源" description="已验证资源优先匹配；未验证资源会明确标注，不可用于紧急救援。" action={<><Button variant="secondary" onClick={() => setAdding(true)}><Plus size={16} /> 添加资源</Button></>} /><div className="service-grid">{state.services.map((s) => <Panel className="service-card" key={s.id}><div className="service-top"><span className={`service-icon trust-${s.trustLevel}`}><CircleHelp size={20} /></span><span className={s.verified ? "verified" : "unverified"}>{s.verified ? <><Check size={13} /> 已验证</> : <><AlertTriangle size={13} /> 未验证</>}</span></div><span className="service-category">{s.category}</span><h2>{s.name}</h2><p>{s.note}</p><div className="service-meta"><span>服务范围</span><strong>{s.coverage}</strong><span>联系方式</span><strong>{s.contact}</strong><span>最近使用</span><strong>{s.lastUsed}</strong></div><Button variant={s.verified ? "secondary" : "quiet"} onClick={() => s.verified ? setContactSvc(s) : verifyService(s)} disabled={verifyBusy}>{s.verified ? "联系服务" : verifyBusy ? "验证中…" : "先完成验证"}</Button></Panel>)}</div>{adding && <AddItemDialog title="添加服务资源" fields={[{ key: "name", label: "资源名称", placeholder: "如 社区卫生站" }, { key: "category", label: "类别", placeholder: "如 医疗服务 / 生活服务" }, { key: "coverage", label: "服务范围", placeholder: "如 3 公里内" }, { key: "contact", label: "联系方式", placeholder: "电话 / 地址" }]} busy={busy} onSubmit={addService} onClose={() => setAdding(false)} />}{contactSvc && <div className="dialog-backdrop" onClick={() => setContactSvc(null)}><div className="simple-dialog" onClick={(e) => e.stopPropagation()}><div className="dialog-warning"><CircleHelp size={21} /></div><h2>{contactSvc.name}</h2><p><strong>服务范围：</strong>{contactSvc.coverage}<br /><strong>联系方式：</strong>{contactSvc.contact}</p><div className="dialog-actions"><Button type="button" variant="quiet" onClick={() => setContactSvc(null)}>关闭</Button><Button type="button" onClick={() => { navigator.clipboard?.writeText(contactSvc.contact).then(() => { notifyGlobal("联系方式已复制到剪贴板"); setContactSvc(null); }).catch(() => notifyGlobal("复制失败，请手动复制")); }}>复制联系方式</Button></div></div></div>}</>; }

function AuditPage() { const state = useProductStore(); const [actor, setActor] = useState("all"); const [risk, setRisk] = useState("all"); const [date, setDate] = useState("all"); const logs = state.auditLogs.filter((l) => (actor === "all" || l.actorType === actor) && (risk === "all" || l.riskLevel === risk) && (date === "all" || (date === "today" ? !l.time.includes("昨天") : l.time.includes("昨天")))); const exportAudit = () => { const head = ["时间", "操作者", "类型", "对象", "动作", "原因", "风险", "结果"]; const rows = logs.map((l) => [l.time, l.actor, l.actorType, l.target, l.action, l.reason, l.riskLevel, l.result === "success" ? "成功" : l.result === "blocked" ? "已拦截" : "失败"]); const csv = [head, ...rows].map((r) => r.map((c) => `"${String(c).replace(/"/g, "\"\"")}"`).join(",")).join("\n"); const blob = new Blob(["\ufeff" + csv], { type: "text/csv;charset=utf-8" }); const url = URL.createObjectURL(blob); const a = document.createElement("a"); a.href = url; a.download = `家有备审计记录-${new Date().toISOString().slice(0, 10)}.csv`; a.click(); URL.revokeObjectURL(url); productStore.audit(state.user.name, "user", "审计导出", "导出审计记录", `导出 ${logs.length} 条记录（CSV）`, "success", "normal"); notifyGlobal(`已导出 ${logs.length} 条审计记录`); }; return <><PageHeader eyebrow="全程留痕" title="安全与审计" description="谁、在什么时候、对什么对象做了什么，为什么，是否成功。" action={<Button variant="secondary" onClick={exportAudit}>导出记录</Button>} /><div className="audit-metrics"><Metric label="今日动作" value="12" note="AI 与家庭成员" icon={Activity} /><Metric label="人工确认" value="3" note="关键动作均有确认" icon={ShieldCheck} tone="amber" /><Metric label="安全拦截" value="2" note="门锁操作 1 次" icon={LockKeyhole} tone="rose" /><Metric label="设备回传" value="8" note="状态均可追溯" icon={Wifi} tone="blue" /></div><Panel className="audit-panel"><div className="audit-toolbar"><div className="audit-controls"><div className="filter-tabs">{[["all", "全部"], ["ai", "AI"], ["user", "用户"], ["device", "设备"], ["rule", "规则"]].map(([k, l]) => <button className={actor === k ? "active" : ""} key={k} onClick={() => setActor(k)}>{l}</button>)}</div><select aria-label="风险级别" value={risk} onChange={(e) => setRisk(e.target.value)}><option value="all">全部风险</option><option value="normal">正常</option><option value="attention">关注</option><option value="warning">警告</option><option value="critical">紧急</option></select><select aria-label="日期范围" value={date} onChange={(e) => setDate(e.target.value)}><option value="all">全部日期</option><option value="today">今天</option><option value="yesterday">昨天</option></select></div><span className="muted">共 {logs.length} 条记录</span></div><div className="audit-table"><div className="audit-head"><span>时间</span><span>操作者</span><span>对象</span><span>动作与原因</span><span>风险</span><span>结果</span></div>{logs.map((l) => <div className="audit-row" key={l.id}><time>{l.time}</time><span className="audit-actor"><span className={`actor-dot ${l.actorType}`} />{l.actor}</span><span><strong>{l.target}</strong></span><span><strong>{l.action}</strong><small>{l.reason}</small></span><RiskBadge level={l.riskLevel} /><span className={`result result-${l.result}`}>{l.result === "success" ? "成功" : l.result === "blocked" ? "已拦截" : "失败"}</span></div>)}</div></Panel></>; }

function NotificationsPage() { const state = useProductStore(); const [filter, setFilter] = useState("all"); const list = state.notifications.filter((n) => filter === "all" || n.category === filter); return <><PageHeader eyebrow="信息中心" title="通知中心" description="风险通知明确呈现，但不会让整个家庭空间变成红色警报。" action={<Button variant="secondary" onClick={() => productStore.markNotificationRead()}>全部标为已读</Button>} /><div className="notification-tabs">{[["all", "全部"], ["urgent", "紧急"], ["action", "待处理"], ["family", "家庭动态"], ["system", "系统"]].map(([k, l]) => <button className={filter === k ? "active" : ""} key={k} onClick={() => setFilter(k)}>{l}</button>)}</div><Panel className="notification-list">{list.map((n) => <button className={`notification-row ${!n.read ? "unread" : ""}`} key={n.id} onClick={() => { productStore.markNotificationRead(n.id); if (n.eventId) navigate(`/events/${n.eventId}`); }}><span className={`notification-icon ${n.category}`}><Bell size={17} /></span><span><strong>{n.title}</strong><p>{n.detail}</p></span><time>{n.time}</time><ChevronRight size={16} /></button>)}</Panel></>; }

function SettingsPage() { const [open, setOpen] = useState<string | null>(null); const [settings, setSettings] = useState<Record<string, string>>({}); const [loaded, setLoaded] = useState(false); const [saved, setSaved] = useState(false); const state = useProductStore(); const load = async () => { if (loaded) return; try { const r = (await apiRequest("/api/settings")) as { settings?: Record<string, string> }; setSettings(r.settings ?? {}); setLoaded(true); } catch { /* 离线时使用默认 */ } }; const save = async (patch: Record<string, string>) => { setSettings((prev) => ({ ...prev, ...patch })); try { await apiRequest("/api/settings", { method: "PUT", body: JSON.stringify({ settings: patch }) }); setSaved(true); setTimeout(() => setSaved(false), 1500); notifyGlobal("设置已保存到云端"); } catch { notifyGlobal("保存失败，请重试"); } }; const rows: Array<{ key: string; title: string; detail: string; icon: IconType }> = [{ key: "family", title: "家庭空间设置", detail: "林家 · 杭州市西湖区文新街道", icon: Home }, { key: "ai", title: "AI 设置", detail: "回复风格、模型与安全偏好", icon: Sparkles }, { key: "notify", title: "通知偏好", detail: "紧急、待处理和家庭动态", icon: Bell }, { key: "privacy", title: "隐私设置", detail: "摄像头、位置与敏感信息", icon: LockKeyhole }, { key: "data", title: "数据管理", detail: "家庭数据、导出与清理", icon: ShieldCheck }]; const toggle = (key: string) => settings[key] === "on" ? "off" : "on"; const exportData = () => { const data = { exportedAt: new Date().toISOString(), app: "家有备 · 家庭安全协同 AI Agent", events: state.events, tasks: state.tasks, members: state.members, devices: state.devices, services: state.services, authorizations: state.authorizations, auditLogs: state.auditLogs, notifications: state.notifications }; const blob = new Blob([JSON.stringify(data, null, 2)], { type: "application/json" }); const url = URL.createObjectURL(blob); const a = document.createElement("a"); a.href = url; a.download = `家有备家庭数据-${new Date().toISOString().slice(0, 10)}.json`; a.click(); URL.revokeObjectURL(url); productStore.audit(state.user.name, "user", "数据导出", "导出家庭数据", "管理员导出完整家庭数据（JSON）", "success", "attention"); notifyGlobal("家庭数据已导出（JSON）"); }; return <><PageHeader eyebrow="家庭空间" title="设置" description="管理家庭空间、AI、通知、隐私和数据。" action={saved && <span className="save-state"><Check size={15} /> 已保存</span>} /><div className="settings-layout"><div>{rows.map(({ key, title, detail, icon }) => <div key={key} className="setting-block"><button className="setting-row" onClick={() => { setOpen(open === key ? null : key); void load(); }}><span className="setting-icon"><Icon icon={icon} size={18} /></span><span><strong>{title}</strong><p>{detail}</p></span><ChevronRight size={17} /></button>{open === key && <Panel className="setting-panel">{key === "family" && <><h3>家庭空间</h3><div className="setting-fields"><label><span>家庭名称</span><input defaultValue="林家" readOnly /></label><label><span>家庭地址</span><input defaultValue="杭州市西湖区文新街道" readOnly /></label><label><span>时区</span><select value={settings.timezone ?? "Asia/Shanghai"} onChange={(e) => save({ timezone: e.target.value })}><option value="Asia/Shanghai">Asia/Shanghai（北京时间）</option><option value="Asia/Hong_Kong">Asia/Hong_Kong</option></select></label></div></>}{key === "ai" && <><h3>AI 回复风格</h3><div className="setting-fields"><label><span>回复风格</span><select value={settings.ai_style ?? "standard"} onChange={(e) => save({ ai_style: e.target.value })}><option value="concise">简洁（要点式）</option><option value="standard">标准（平衡）</option><option value="caring">关怀（更详细安抚）</option></select></label></div><div className="dialog-note"><ShieldCheck size={15} /><span>高风险操作始终需要人工确认，模型无法关闭此边界。</span></div></>}{key === "notify" && <><h3>通知偏好</h3>{[{ k: "notify_urgent", l: "紧急事件通知" }, { k: "notify_action", l: "待处理事项提醒" }, { k: "notify_family", l: "家庭动态" }].map(({ k, l }) => <div className="toggle-row" key={k}><span>{l}</span><button className={`switch ${settings[k] === "off" ? "" : "on"}`} aria-label={l} aria-pressed={settings[k] !== "off"} onClick={() => save({ [k]: toggle(k) })}><i /></button></div>)}</>}{key === "privacy" && <><h3>隐私设置</h3>{[{ k: "privacy_location", l: "家庭成员位置共享" }, { k: "privacy_camera", l: "摄像头画面分析通知" }].map(({ k, l }) => <div className="toggle-row" key={k}><span>{l}</span><button className={`switch ${settings[k] === "off" ? "" : "on"}`} aria-label={l} aria-pressed={settings[k] !== "off"} onClick={() => save({ [k]: toggle(k) })}><i /></button></div>)}<div className="dialog-note"><LockKeyhole size={15} /><span>敏感信息只提供给已授权的家庭成员，AI 仅使用授权范围的数据。</span></div></>}{key === "data" && <><h3>数据管理</h3><div className="setting-actions"><Button variant="secondary" onClick={exportData}>导出家庭数据（JSON）</Button><Button variant="quiet" onClick={() => { if (confirm("确定要重置演示状态吗？将恢复种子数据。")) { productStore.reset(); notifyGlobal("演示状态已重置"); } }}>重置演示状态</Button></div><p className="muted">导出包含事件、任务、设备、服务、授权与审计记录，不含登录凭据。</p></>}</Panel>}</div>)}</div><Panel className="demo-setting"><span className="eyebrow">运行环境</span><h2>{state.demoMode ? "Mock 演示模式" : "真实云端模式"}</h2><p>{state.demoMode ? "使用本地模拟数据演示完整闭环。" : "已连接 Cloudflare 云端，数据落库 D1，AI 为真实大模型。"}</p><div className="toggle-row"><span>AI 高风险操作始终拦截</span><span className="locked"><LockKeyhole size={13} /> 已锁定</span></div></Panel></div></>; }

function DemoPage() { const state = useProductStore(); const [busy, setBusy] = useState(""); const run = (kind: Parameters<typeof productStore.triggerDemo>[0], label: string, path?: string) => { setBusy(kind); setTimeout(() => { productStore.triggerDemo(kind); setBusy(""); if (path) navigate(path); }, 350); }; const scenarios = [{ kind: "elderly" as const, title: "老人长时间未活动", detail: "事件 → AI 分析 → 联系任务 → 逐级升级 → 事件解决", icon: Users, tone: "teal", path: "/events/E001" }, { kind: "stranger" as const, title: "陌生人请求开门", detail: "AI 建议 → 风险规则 → 授权确认 → 拒绝并审计", icon: LockKeyhole, tone: "rose", path: "/authorizations" }, { kind: "smoke" as const, title: "烟雾告警", detail: "硬告警优先 → 人工复核 → 状态回传", icon: AlertTriangle, tone: "amber", path: "/events/E003" }, { kind: "pet" as const, title: "宠物喂食超时", detail: "超时检测 → 提醒照护者 → 请求完成证据", icon: Clock3, tone: "blue", path: "/tasks/T004" }, { kind: "offline" as const, title: "设备离线", detail: "设备离线 → 系统通知 → 重新同步", icon: Wifi, tone: "gray", path: "/devices/D008" }, { kind: "failure" as const, title: "AI 输出异常", detail: "模型不可用 → 规则降级 → 不执行外部动作", icon: Bot, tone: "gray", path: "/ai" }]; return <><PageHeader eyebrow="课程展示" title="Demo 控制台" description="一键触发可观察的状态链路，现场演示不依赖真实设备和模型。" action={<Button variant="secondary" onClick={() => { productStore.reset(); notifyGlobal("Demo 状态已重置") }}><RefreshCw size={15} /> 重置全部状态</Button>} /><Panel className="demo-intro"><div className="demo-play"><Zap size={25} /></div><div><strong>当前为 Mock 演示模式</strong><p>所有操作仍遵循“AI 规划、规则设边界、人工做确认”，状态会同步到 Dashboard、事件、任务、授权和审计。</p></div><span className="demo-live"><i /> 可演示</span></Panel>{busy ? <LoadingSkeleton /> : <div className="demo-grid">{scenarios.map((s) => <Panel className="demo-card" key={s.kind}><span className={`demo-icon ${s.tone}`}><Icon icon={s.icon} size={21} /></span><h2>{s.title}</h2><p>{s.detail}</p><Button onClick={() => run(s.kind, s.title, s.path)} disabled={Boolean(busy)}>{busy === s.kind ? "生成中…" : "触发场景"} <ArrowRight size={15} /></Button></Panel>)}</div>}<Panel className="demo-state"><SectionTitle title="当前演示状态" detail="实时读取统一数据模型" /><div className="state-chips"><span><strong>{state.events.filter((e) => e.status !== "closed").length}</strong> 活跃事件</span><span><strong>{state.tasks.filter((t) => t.status !== "completed").length}</strong> 未完成任务</span><span><strong>{state.authorizations.filter((a) => a.status === "pending").length}</strong> 待确认授权</span><span><strong>{state.auditLogs.length}</strong> 审计记录</span></div></Panel></>; }

let globalNotify: ((text: string) => void) | null = null; function notifyGlobal(text: string) { globalNotify?.(text); }
function Login({ onSuccess }: { onSuccess: () => void }) {
  const [needsSetup, setNeedsSetup] = useState(false);
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState("");
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [name, setName] = useState("");
  useEffect(() => {
    if (!authApi.enabled) return;
    void authApi.setupStatus().then((status) => setNeedsSetup(status.needsSetup)).catch(() => {});
  }, []);
  const submit = async (e: FormEvent) => {
    e.preventDefault();
    if (!email.trim() || password.length < 8) { setError(needsSetup ? "请填写邮箱和至少 8 位密码" : "请填写邮箱和密码"); return; }
    setBusy(true); setError("");
    try {
      if (needsSetup) {
        await authApi.setup(email.trim(), password, name.trim() || undefined);
      } else {
        await authApi.login(email.trim(), password);
      }
      onSuccess();
      // 登录成功后注册推送（真实模式，静默失败）
      void ensurePushSubscription();
    } catch (err) {
      setError(err instanceof Error ? err.message.replace(/^API \d+: /, "") : "操作失败，请重试");
    } finally {
      setBusy(false);
    }
  };
  return <div className="welcome"><div className="welcome-mark"><span /><span /><span /></div><div className="eyebrow">家庭安全协同 AI Agent</div><h1>{needsSetup ? "创建你的家庭管理员账号" : "登录家庭空间"}</h1><p>{needsSetup ? "这是首次使用：设置管理员邮箱与密码，之后家庭成员可通过邀请加入。" : "使用家庭管理员账号登录后，查看家庭空间与协同任务。"}</p><form className="login-form" onSubmit={submit}><input aria-label="邮箱" type="email" autoComplete="email" placeholder="邮箱" value={email} onChange={(e) => setEmail(e.target.value)} />{needsSetup && <input aria-label="称呼" type="text" autoComplete="name" placeholder="称呼（可选，默认：家庭管理员）" value={name} onChange={(e) => setName(e.target.value)} />}<input aria-label="密码" type="password" autoComplete={needsSetup ? "new-password" : "current-password"} placeholder="密码（至少 8 位）" value={password} onChange={(e) => setPassword(e.target.value)} />{error && <p className="login-error" role="alert">{error}</p>}<Button type="submit" disabled={busy}>{busy ? "处理中…" : needsSetup ? "创建账号并进入" : "登录"}</Button></form><small className="login-note">账号密码仅用于访问你的家庭空间；密钥与家庭数据不会发送给第三方。</small></div>;
}
function AppRouter({ initialPath }: { initialPath: string }) { const path = usePath(initialPath); const state = useProductStore(); const [toast, setToast] = useState(""); useEffect(() => { globalNotify = setToast; void productStore.hydrate(); return () => { globalNotify = null; }; }, []); if (state.hydrationStatus === "unauthorized") return <Login onSuccess={() => productStore.retryHydrate()} />; let content: React.ReactNode; if (path === "/" || path === "/dashboard") content = <Dashboard />; else if (path === "/welcome") content = <Welcome />; else if (path === "/onboarding") content = <Onboarding />; else if (path === "/ai") content = <Assistant />; else if (path === "/events") content = <EventsPage />; else if (path.startsWith("/events/")) content = <EventDetail id={path.split("/")[2]} />; else if (path === "/tasks") content = <TasksPage />; else if (path.startsWith("/tasks/")) content = <TaskDetail id={path.split("/")[2]} />; else if (path === "/authorizations") content = <AuthorizationsPage />; else if (path === "/members") content = <MembersPage />; else if (path.startsWith("/members/")) content = <MembersPage id={path.split("/")[2]} />; else if (path === "/devices") content = <DevicesPage />; else if (path.startsWith("/devices/")) content = <DevicesPage id={path.split("/")[2]} />; else if (path === "/services") content = <ServicesPage />; else if (path === "/audit") content = <AuditPage />; else if (path === "/notifications") content = <NotificationsPage />; else if (path === "/settings") content = <SettingsPage />; else if (path === "/demo") content = <DemoPage />; else content = <NotFound />; if (state.hydrationStatus === "idle" || state.hydrationStatus === "loading") content = <div className="bootstrap-state"><PageHeader eyebrow="安全连接" title="正在连接家庭空间" description="正在校验完整家庭数据；加载完成前不会开放敏感操作。" /><LoadingSkeleton /></div>; else if (state.hydrationStatus === "error") content = <div className="bootstrap-state"><Panel className="error-state"><AlertTriangle size={19} /><div><strong>无法连接真实家庭数据</strong><p>{state.lastError}</p></div><Button variant="secondary" onClick={() => productStore.retryHydrate()}>重新连接</Button></Panel></div>; return <AppShell path={path}>{content}{toast && <Toast text={toast} onClose={() => setToast("")} />}</AppShell>; }
function Welcome() { return <div className="welcome"><div className="welcome-mark"><span /><span /><span /></div><div className="eyebrow">家庭安全协同 AI Agent</div><h1>重要的事，<br /><em>不只提醒，还要有人完成。</em></h1><p>家有备让家庭成员在异地照护、老人独居和突发事务中保持协同：AI 理解情况，家庭一起做决定。</p><div className="welcome-points"><span><Sparkles size={16} />AI 理解</span><span><Users size={16} />家庭协作</span><span><ShieldCheck size={16} />安全确认</span></div><div className="welcome-actions"><Button onClick={() => navigate("/onboarding")}>进入我的家庭 <ArrowRight size={16} /></Button><Button variant="secondary" onClick={() => navigate("/")}>使用 Demo 家庭</Button></div></div>; }
function Onboarding() { const [step, setStep] = useState(1); const steps = [{ title: "创建家庭空间", detail: "把家庭成员、地址和应急联系人放在一个可信的协同空间。", icon: Home }, { title: "添加家庭成员", detail: "按成员角色设置可见信息和可访问的设备范围。", icon: Users }, { title: "设置紧急联系人", detail: "为关键场景准备已经验证的家庭、邻里和社区资源。", icon: Bell }, { title: "设定基础规则", detail: "明确什么可以自动提醒，什么每次都需要你确认。", icon: ShieldCheck }]; const current = steps[step - 1]; return <div className="onboarding"><div className="onboarding-top"><button className="brand-light" onClick={() => navigate("/")}><span className="brand-mark"><span /><span /><span /></span><strong>家有备</strong></button><button className="skip" onClick={() => navigate("/")}>跳过引导</button></div><div className="onboarding-body"><div className="stepper">{steps.map((s, i) => <div className={step >= i + 1 ? "active" : ""} key={s.title}><span>{step > i + 1 ? <Check size={14} /> : i + 1}</span><small>{s.title}</small></div>)}</div><div className="onboarding-card"><span className="onboarding-icon"><Icon icon={current.icon} size={27} /></span><div className="eyebrow">第 {step} 步 / 共 4 步</div><h1>{current.title}</h1><p>{current.detail}</p><div className="onboarding-placeholder"><div><Check size={18} /> Demo 家庭已准备好示例数据</div><div><ShieldCheck size={18} /> 你可以随时修改授权与隐私设置</div></div><div className="onboarding-actions"><Button variant="secondary" onClick={() => setStep(Math.max(1, step - 1))} disabled={step === 1}>上一步</Button>{step < 4 ? <Button onClick={() => setStep(step + 1)}>继续 <ArrowRight size={16} /></Button> : <Button onClick={() => navigate("/")}>进入家庭空间 <ArrowRight size={16} /></Button>}</div></div></div></div>; }
function NotFound({ title = "页面不存在", detail = "这个家庭空间还没有配置该页面。", backPath = "/" }: { title?: string; detail?: string; backPath?: string }) { return <div className="not-found"><CircleHelp size={28} /><h1>{title}</h1><p>{detail}</p><Button onClick={() => navigate(backPath)}>返回上一层</Button></div>; }
export default function JiaYouBeiApp({ initialPath = "/" }: { initialPath?: string }) { return <AppRouter initialPath={initialPath} />; }
